from fastapi import FastAPI
from neo4j import GraphDatabase
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np
import os

app = FastAPI()

driver = GraphDatabase.driver(
    os.getenv("NEO4J_URI"),
    auth=(os.getenv("NEO4J_USER"), os.getenv("NEO4J_PASSWORD"))
)


@app.get("/graph")
def get_graph(limit: int = 100):

    query = """
    MATCH (a)-[r]->(b)
    RETURN a, r, b
    LIMIT $limit
    """

    with driver.session() as session:
        result = session.run(query, limit=limit)

        nodes = {}
        edges = []

        for record in result:

            a = record["a"]
            b = record["b"]
            r = record["r"]

            nodes[a.id] = dict(a)
            nodes[b.id] = dict(b)

            edges.append({
                "source": a.id,
                "target": b.id,
                "type": r.type
            })

    return {
        "nodes": list(nodes.values()),
        "edges": edges
    }


def scam_score(text):

    score = 0

    keywords = [
        "urgent", "instant", "guaranteed",
        "advance fee", "profit", "no risk"
    ]

    for k in keywords:
        if k in text.lower():
            score += 0.15

    return min(score, 1.0)


@app.get("/scam-score/{post_id}")
def get_scam_score(post_id: str):

    query = """
    MATCH (p:Post {id:$id})
    RETURN p.text AS text
    """

    with driver.session() as session:
        res = session.run(query, id=post_id).single()

        if not res:
            return {"error": "not found"}

        text = res["text"]

        return {
            "post_id": post_id,
            "score": scam_score(text)
        }
    

@app.get("/similar-posts/{post_id}")
def similar_posts(post_id: str):

    query = """
    MATCH (p:Post)
    RETURN p.id AS id, p.embedding AS emb
    """

    with driver.session() as session:
        data = session.run(query).data()

    target = None

    for d in data:
        if d["id"] == post_id:
            target = np.array(d["emb"])
            break

    if target is None:
        return {"error": "not found"}

    results = []

    for d in data:

        if d["id"] == post_id:
            continue

        emb = np.array(d["emb"])

        sim = cosine_similarity(
            [target],
            [emb]
        )[0][0]

        if sim > 0.75:
            results.append({
                "id": d["id"],
                "similarity": float(sim)
            })

    return results

